#pswScreen,#pswScreen :where(*:not(svg,svg *)),#pswScreen :where(*:not(svg,svg *))::before,#pswScreen :where(*:not(svg,svg *))::after{all:revert}
@keyframes pp_auraDrift { 
  0%, 100% { transform: translate3d(0px, 0px, 0px) scale(1); }
  50% { transform: translate3d(5%, 4%, 0px) scale(1.09); }
}
@keyframes pp_mePulse { 
  0%, 100% { box-shadow: rgba(86, 200, 245, 0.28) 0px 0px 0px 4px; }
  50% { box-shadow: rgba(86, 200, 245, 0.04) 0px 0px 0px 9px; }
}
#pswScreen .leaflet-pane,#pswScreen .leaflet-tile,#pswScreen .leaflet-marker-icon,#pswScreen .leaflet-marker-shadow,#pswScreen .leaflet-tile-container,#pswScreen .leaflet-pane > svg,#pswScreen .leaflet-pane > canvas,#pswScreen .leaflet-zoom-box,#pswScreen .leaflet-image-layer,#pswScreen .leaflet-layer{position: absolute; left: 0px; top: 0px;}
#pswScreen .leaflet-tile,#pswScreen .leaflet-marker-icon,#pswScreen .leaflet-marker-shadow{user-select: none; -webkit-user-drag: none;}
#pswScreen .leaflet-tile::selection{background: transparent;}
#pswScreen .leaflet-container .leaflet-overlay-pane svg{max-width: none !important; max-height: none !important;}
#pswScreen .leaflet-container .leaflet-marker-pane img,#pswScreen .leaflet-container .leaflet-shadow-pane img,#pswScreen .leaflet-container .leaflet-tile-pane img,#pswScreen .leaflet-container img.leaflet-image-layer,#pswScreen .leaflet-container .leaflet-tile{width: auto; padding: 0px; max-width: none !important; max-height: none !important;}
#pswScreen .leaflet-container img.leaflet-tile{mix-blend-mode: plus-lighter;}
#pswScreen .leaflet-container.leaflet-touch-zoom{touch-action: pan-x pan-y;}
#pswScreen .leaflet-tile{filter: inherit; visibility: hidden;}
#pswScreen .leaflet-tile-loaded{visibility: inherit;}
#pswScreen .leaflet-overlay-pane svg{}
#pswScreen .leaflet-pane{z-index: 400;}
#pswScreen .leaflet-tile-pane{z-index: 200;}
#pswScreen .leaflet-overlay-pane{z-index: 400;}
#pswScreen .leaflet-shadow-pane{z-index: 500;}
#pswScreen .leaflet-marker-pane{z-index: 600;}
#pswScreen .leaflet-tooltip-pane{z-index: 650;}
#pswScreen .leaflet-popup-pane{z-index: 700;}
#pswScreen .leaflet-map-pane svg{z-index: 200;}
#pswScreen .leaflet-top,#pswScreen .leaflet-bottom{position: absolute; z-index: 1000; pointer-events: none;}
#pswScreen .leaflet-top{top: 0px;}
#pswScreen .leaflet-right{right: 0px;}
#pswScreen .leaflet-bottom{bottom: 0px;}
#pswScreen .leaflet-left{left: 0px;}
#pswScreen .leaflet-zoom-animated{transform-origin: 0px 0px;}
#pswScreen svg.leaflet-zoom-animated{will-change: transform;}
#pswScreen .leaflet-interactive{cursor: pointer;}
#pswScreen .leaflet-popup-pane,#pswScreen .leaflet-control{cursor: auto;}
#pswScreen .leaflet-marker-icon,#pswScreen .leaflet-marker-shadow,#pswScreen .leaflet-image-layer,#pswScreen .leaflet-pane > svg path,#pswScreen .leaflet-tile-container{pointer-events: none;}
#pswScreen .leaflet-marker-icon.leaflet-interactive,#pswScreen .leaflet-image-layer.leaflet-interactive,#pswScreen .leaflet-pane > svg path.leaflet-interactive,#pswScreen svg.leaflet-image-layer.leaflet-interactive path{pointer-events: auto;}
#pswScreen .leaflet-marker-icon,#pswScreen .leaflet-marker-shadow{display: block;}
#pswScreen .leaflet-container.leaflet-touch-drag{touch-action: pinch-zoom;}
#pswScreen .leaflet-container.leaflet-touch-drag.leaflet-touch-zoom{touch-action: none;}
#pswScreen .leaflet-container a{color: rgb(0, 120, 168);}
#pswScreen .leaflet-control{float: left; clear: both;}
#pswScreen .leaflet-right .leaflet-control{margin-right: 10px;}
#pswScreen .leaflet-top .leaflet-control{margin-top: 10px;}
#pswScreen .leaflet-bottom .leaflet-control{margin-bottom: 10px;}
#pswScreen .leaflet-left .leaflet-control{margin-left: 10px;}
#pswScreen .leaflet-grab{cursor: grab;}
#pswScreen .leaflet-bar{box-shadow: rgba(0, 0, 0, 0.65) 0px 1px 5px; border-radius: 4px;}
#pswScreen .leaflet-bar a{background-color: rgb(255, 255, 255); border-bottom: 1px solid rgb(204, 204, 204); width: 26px; height: 26px; line-height: 26px; display: block; text-align: center; text-decoration: none; color: black;}
#pswScreen .leaflet-bar a,#pswScreen .leaflet-control-layers-toggle{background-position: 50% 50%; background-repeat: no-repeat; display: block;}
#pswScreen .leaflet-bar a:first-child{border-top-left-radius: 4px; border-top-right-radius: 4px;}
#pswScreen .leaflet-bar a:last-child{border-bottom-left-radius: 4px; border-bottom-right-radius: 4px; border-bottom: none;}
#pswScreen .leaflet-touch .leaflet-bar a{width: 30px; height: 30px; line-height: 30px;}
#pswScreen .leaflet-touch .leaflet-bar a:first-child{border-top-left-radius: 2px; border-top-right-radius: 2px;}
#pswScreen .leaflet-touch .leaflet-bar a:last-child{border-bottom-left-radius: 2px; border-bottom-right-radius: 2px;}
#pswScreen .leaflet-control-zoom-in,#pswScreen .leaflet-control-zoom-out{font: bold 18px "Lucida Console", Monaco, monospace; text-indent: 1px;}
#pswScreen .leaflet-touch .leaflet-control-zoom-in,#pswScreen .leaflet-touch .leaflet-control-zoom-out{font-size: 22px;}
#pswScreen .leaflet-container .leaflet-control-attribution{background: rgba(255, 255, 255, 0.8); margin: 0px;}
#pswScreen .leaflet-control-attribution,#pswScreen .leaflet-control-scale-line{padding: 0px 5px; color: rgb(51, 51, 51); line-height: 1.4;}
#pswScreen .leaflet-control-attribution a{text-decoration: none;}
#pswScreen .leaflet-attribution-flag{width: 1em; height: 0.6669em; display: inline !important; vertical-align: baseline !important;}
#pswScreen .leaflet-touch .leaflet-control-attribution,#pswScreen .leaflet-touch .leaflet-control-layers,#pswScreen .leaflet-touch .leaflet-bar{box-shadow: none;}
#pswScreen .leaflet-touch .leaflet-control-layers,#pswScreen .leaflet-touch .leaflet-bar{border: 2px solid rgba(0, 0, 0, 0.2); background-clip: padding-box;}
#pswScreen #hp_leaflet-map{height: 260px !important;}
#pswScreen *,#pswScreen ::before,#pswScreen ::after{box-sizing: border-box; min-width: 0px;}
#pswScreen img,#pswScreen picture,#pswScreen video,#pswScreen canvas,#pswScreen svg{max-width: 100%; height: auto; display: block;}
#pswScreen *,#pswScreen ::before,#pswScreen ::after{box-sizing: border-box; margin: 0px; padding: 0px; -webkit-tap-highlight-color: transparent;}
#pswScreen .feed-see-more{display: flex; align-items: center; justify-content: center; gap: 7px; padding: 13px; margin: 6px 0px 2px; font-family: var(--rb-mono); font-size: 11px; letter-spacing: 1.5px; text-transform: uppercase; color: var(--psw); background: rgba(86, 200, 245, 0.06); border: 1px solid rgba(86, 200, 245, 0.2); border-radius: 12px; cursor: pointer; touch-action: manipulation; transition: background .14s var(--e);}
#pswScreen .feed-see-more svg{width: 14px; height: 14px;}
#pswScreen .toast.show{opacity: 1; transform: translateX(-50%) translateY(0px);}
#pswScreen *,#pswScreen,#pswScreen{box-sizing: border-box; min-width: 0px;}
#pswScreen{overflow: clip auto; overscroll-behavior-y: contain; text-size-adjust: 100%; max-width: 100%;}
#pswScreen,#pswScreen .pd-body{overflow-x: clip;}
#pswScreen .pd-body{overflow-x: clip; min-height: 762px; margin: 0px; -webkit-tap-highlight-color: transparent; overflow-wrap: anywhere; word-break: break-word;}
#pswScreen img,#pswScreen canvas,#pswScreen svg{max-width: 100%; height: auto; display: block;}
#pswScreen input,#pswScreen select,#pswScreen textarea,#pswScreen button{font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; font-size: max(16px, 1em); max-width: 100%;}
#pswScreen .leaflet-container{max-width: 100%; width: 100% !important; height: 100% !important;}
#pswScreen *,#pswScreen,#pswScreen{box-sizing: border-box; margin: 0px; padding: 0px; -webkit-tap-highlight-color: transparent;}
#pswScreen{--bg: #050608; --bg2: #0E1116; --bg3: #151A21; --bg4: #1C222B; --accent: #56C8F5; --teal: #56C8F5; --teal2: #3DAEE0; --teal3: #A8E2FF; --gold: #F0B549; --amber: #FFB340; --purple2: #A78BFA; --red: #FF5D5D; --green: #34D399; --green2: #5EEAB5; --text: #F2F4F6; --muted: #9AA7B0; --muted2: rgba(242,244,246,.62); --muted3: rgba(242,244,246,.85); --border: rgba(255,255,255,.07); --border2: rgba(255,255,255,.13); --border3: rgba(255,255,255,.22); --mono: 'DM Mono',monospace; --sans: 'DM Sans',sans-serif; --serif: 'Cormorant Garamond',serif; --rb-void: #06080c; --rb-base: #0a0e14; --rb-panel: #0e131b; --rb-elev: #121826; --rb-line: rgba(255,255,255,.07); --rb-line2: rgba(255,255,255,.13); --rb-text: #eef2f6; --rb-dim: #a6b3bf; --rb-serif: 'Fraunces',serif; --rb-sans: 'Space Grotesk','DM Sans',sans-serif; --rb-mono: 'DM Mono',monospace; --e: cubic-bezier(.22,1,.36,1); --psw: #56C8F5; --psw-deep: #3DAEE0; --psw-light: #A8E2FF; --psw-ink: #04141C; --psw-glow: rgba(86,200,245,.16); --safe-bottom: env(safe-area-inset-bottom,0px); --safe-top: env(safe-area-inset-top,0px);}
#pswScreen{height: 100%; background: var(--bg);}
#pswScreen .pd-body{font-family: var(--sans); background: var(--bg); color: var(--text); min-height: 100%; overflow-x: hidden; text-size-adjust: 100%; padding-bottom: calc(64px + var(--safe-bottom));}
#pswScreen button{font-family: var(--sans); cursor: pointer; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; background: none;}
#pswScreen input,#pswScreen select,#pswScreen textarea{font-family: var(--sans); font-size: 16px;}
#pswScreen a{color: inherit; text-decoration: none;}
#pswScreen #pp_lock{position: fixed; inset: 0px; background: radial-gradient(120% 80% at 50% -10%,rgba(86,200,245,.06),transparent 60%),var(--rb-void); z-index: 999; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 26px; padding: 0px 24px;}
#pswScreen .lock-logo{font-family: var(--rb-serif); font-size: 36px; color: var(--rb-text); font-weight: 300; letter-spacing: 0.5px; text-align: center; margin-bottom: 3px; line-height: 1;}
#pswScreen .lock-logo em{color: var(--psw); font-style: italic; font-weight: 400;}
#pswScreen .lock-sub{font-family: var(--rb-mono); font-size: 11px; letter-spacing: 4px; text-transform: uppercase; color: var(--rb-dim);}
#pswScreen .lock-step{display: none; flex-direction: column; align-items: center; gap: 16px; width: 100%; max-width: 320px;}
#pswScreen .lock-step.active{display: flex;}
#pswScreen .lock-label{font-family: var(--rb-mono); font-size: 11px; letter-spacing: 2.5px; text-transform: uppercase; color: var(--rb-dim);}
#pswScreen .lock-input{width: 100%; background: var(--rb-panel); border: 1px solid var(--rb-line2); color: var(--rb-text); padding: 16px; font-family: var(--rb-sans); font-size: 16px; border-radius: 14px; text-align: center; transition: border-color .18s var(--e),box-shadow .18s var(--e);}
#pswScreen .lock-input:focus{outline: none; border-color: var(--psw); box-shadow: 0 0 0 4px var(--psw-glow);}
#pswScreen .lock-input::placeholder{color: var(--rb-dim); opacity: 0.7;}
#pswScreen .lock-bio{width: 100%; padding: 14px; display: flex; align-items: center; justify-content: center; gap: 10px; background: linear-gradient(160deg, rgba(86, 200, 245, 0.1), rgba(86, 200, 245, 0.03)); border: 1px solid rgba(86, 200, 245, 0.3); border-radius: 14px; color: var(--psw-light); font-family: var(--rb-sans); font-size: 14px; font-weight: 500; cursor: pointer; margin-bottom: 6px; touch-action: manipulation; transition: transform .12s var(--e);}
#pswScreen .lock-bio:active{transform: scale(0.98);}
#pswScreen .lock-bio svg{width: 20px; height: 20px; color: var(--psw); flex-shrink: 0;}
#pswScreen .lock-btn{width: 100%; background: linear-gradient(135deg,var(--psw),var(--psw-deep)); color: var(--psw-ink); padding: 16px; font-family: var(--rb-mono); font-size: 11px; font-weight: 500; letter-spacing: 2.5px; text-transform: uppercase; border-radius: 14px; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; cursor: pointer; box-shadow: 0 12px 30px -8px var(--psw-glow); transition: transform .12s var(--e),box-shadow .12s var(--e);}
#pswScreen .lock-btn:active{transform: scale(0.97); box-shadow: 0 6px 16px -8px var(--psw-glow);}
#pswScreen .lock-dots{display: flex; gap: 14px; justify-content: center;}
#pswScreen .lock-dot{width: 12px; height: 12px; border-radius: 50%; border: 1px solid var(--rb-line2); background: transparent; transition: all .18s var(--e);}
#pswScreen .lock-pad{display: grid; grid-template-columns: repeat(3, 72px); gap: 12px; justify-content: center;}
#pswScreen .lock-key{width: 72px; height: 72px; border-radius: 50%; border: 1px solid var(--rb-line2); background: rgba(255, 255, 255, 0.024); color: var(--rb-text); font-family: var(--rb-sans); font-size: 24px; font-weight: 300; display: flex; align-items: center; justify-content: center; transition: all .12s var(--e); user-select: none; touch-action: manipulation;}
#pswScreen .lock-key:active{background: rgba(255, 255, 255, 0.07); border-color: var(--rb-line2); color: var(--rb-text);}
#pswScreen .lock-key.del{color: var(--rb-dim);}
#pswScreen .lock-key.del svg{width: 22px; height: 22px;}
#pswScreen .lock-key.empty{background: none; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; pointer-events: none;}
#pswScreen .lock-err{font-family: var(--rb-mono); font-size: 11px; color: var(--red); letter-spacing: 1px; opacity: 0; transition: opacity 0.3s; text-align: center;}
#pswScreen .topbar{position: sticky; top: 0px; z-index: 100; height: 54px; display: flex; align-items: center; justify-content: space-between; padding: 0px 14px; background: rgba(7, 9, 12, 0.96); border-bottom: 1px solid var(--border); backdrop-filter: blur(20px);}
#pswScreen .hamburger-btn{width: 36px; height: 36px; border-radius: 8px; border: 1px solid var(--border2); background: transparent; color: var(--muted2); display: flex; align-items: center; justify-content: center; cursor: pointer; touch-action: manipulation; flex-shrink: 0;}
#pswScreen .hamburger-btn:active{background: var(--bg3);}
#pswScreen .drawer-overlay{display: none; position: fixed; inset: 0px; z-index: 400; background: rgba(0, 0, 0, 0.6);}
#pswScreen .drawer{position: fixed; top: 0px; right: -280px; bottom: 0px; width: 260px; background: var(--bg2); border-left: 1px solid var(--border); z-index: 401; transition: right 0.28s cubic-bezier(0.4, 0, 0.2, 1); padding: 0px; overflow-y: auto;}
#pswScreen .drawer-header{padding: 20px 18px 14px; border-bottom: 1px solid var(--border); display: flex; align-items: center; justify-content: space-between;}
#pswScreen .drawer-close{width: 32px; height: 32px; border-radius: 6px; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; background: var(--bg3); color: var(--muted2); font-size: 16px; cursor: pointer; display: flex; align-items: center; justify-content: center;}
#pswScreen .drawer-item{display: flex; align-items: center; gap: 12px; padding: 14px 18px; border-bottom: 1px solid var(--border); cursor: pointer; color: var(--text); font-size: 14px; touch-action: manipulation; transition: background 0.12s;}
#pswScreen .drawer-item:active{background: var(--bg3);}
#pswScreen .drawer-item svg{width: 18px; height: 18px; color: var(--teal2);}
#pswScreen .drawer-lbl{flex: 1 1 0%;}
#pswScreen .drawer-badge{font-family: var(--mono); font-size: 12px; background: var(--teal2); color: rgb(0, 0, 0); border-radius: 100px; padding: 2px 7px;}
#pswScreen .psw-info{display: flex; align-items: center; gap: 10px; min-width: 0px; overflow: hidden;}
#pswScreen .no-shrink{flex-shrink: 0;}
#pswScreen .psw-avatar{width: 32px; height: 32px; border-radius: 50%; background: var(--bg3); border: 1px solid var(--border2); display: flex; align-items: center; justify-content: center; font-family: var(--mono); font-size: 11px; color: var(--teal2); font-weight: 500; flex-shrink: 0;}
#pswScreen .psw-name-top{font-size: 14px; font-weight: 500; color: var(--text); min-width: 0px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;}
#pswScreen .psw-role{font-family: var(--mono); font-size: 11px; letter-spacing: 2px; text-transform: uppercase; color: var(--teal2); margin-top: 1px; min-width: 0px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;}
#pswScreen .shift-pill{flex-shrink: 0; font-family: var(--mono); font-size: 11px; letter-spacing: 1px; text-transform: uppercase; padding: 5px 10px; border-radius: 100px; background: rgba(224, 154, 61, 0.15); color: var(--amber); border: 1px solid rgba(224, 154, 61, 0.3);}
#pswScreen .section{display: none; padding-bottom: 8px;}
#pswScreen .section.active{display: block;}
#pswScreen .section-header{display: flex; align-items: center; justify-content: space-between; padding: 12px 14px 8px;}
#pswScreen .section-title{font-size: 12px; letter-spacing: 3px; text-transform: uppercase; color: var(--muted2);}
#pswScreen .stats-strip{display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; background: var(--rb-line); border-top: 1px solid var(--rb-line); border-bottom: 1px solid var(--rb-line); backdrop-filter: blur(12px);}
#pswScreen .stat-card{background: linear-gradient(180deg,rgba(255,255,255,.025),transparent),var(--rb-panel); padding: 14px 6px; text-align: center;}
#pswScreen .stat-val{font-family: var(--rb-mono); font-size: 19px; font-weight: 500; color: var(--rb-text); line-height: 1; letter-spacing: -0.5px;}
#pswScreen .stat-lbl{font-family: var(--rb-mono); font-size: 10px; letter-spacing: 2px; text-transform: uppercase; color: var(--rb-dim); margin-top: 5px;}
#pswScreen .stat-card.hi .stat-val{color: var(--psw);}
#pswScreen .stat-card.pay .stat-val{color: var(--green2);}
#pswScreen .pay-hero{margin: 12px; background: linear-gradient(165deg,rgba(86,200,245,.05),rgba(255,255,255,.012)),var(--rb-panel); border: 1px solid var(--rb-line2); border-radius: 16px; overflow: hidden; box-shadow: rgba(255, 255, 255, 0.05) 0px 1px 0px inset, rgba(0, 0, 0, 0.85) 0px 14px 34px -20px;}
#pswScreen .pay-hero-hdr{padding: 13px 16px; border-bottom: 1px solid var(--rb-line); display: flex; align-items: center; justify-content: space-between;}
#pswScreen .pay-hero-toggle{display: inline-flex; gap: 4px; background: rgba(255, 255, 255, 0.06); padding: 3px; border-radius: 8px;}
#pswScreen .pay-chip{font-family: var(--rb-mono); font-size: 11px; letter-spacing: 0.04em; text-transform: uppercase; color: var(--rb-dim); background: transparent; border: 0px; padding: 7px 10px; border-radius: 6px; cursor: pointer;}
#pswScreen .pay-chip.is-on{background: rgba(255, 255, 255, 0.12); color: var(--rb-text);}
#pswScreen .pay-hero-period{font-family: var(--rb-mono); font-size: 11px; color: var(--rb-dim);}
#pswScreen .pay-hero-body{padding: 16px;}
#pswScreen .pay-hero-total{font-family: var(--rb-mono); font-size: 36px; font-weight: 500; color: var(--gold); line-height: 1; margin-bottom: 14px; letter-spacing: -1px;}
#pswScreen .pay-hero-row{display: flex; justify-content: space-between; align-items: center; padding: 7px 0px; border-bottom: 1px solid var(--rb-line);}
#pswScreen .pay-hero-row:last-child{border-bottom-width: medium; border-bottom-style: none; border-bottom-color: currentcolor;}
#pswScreen .pay-hero-key{font-family: var(--rb-mono); font-size: 10px; letter-spacing: 1.5px; text-transform: uppercase; color: var(--rb-dim);}
#pswScreen .pay-hero-val{font-family: var(--rb-mono); font-size: 12px; color: var(--rb-text);}
#pswScreen .feed-card{margin: 0px 12px 12px; background: var(--rb-panel); border: 1px solid var(--rb-line); border-radius: 16px; overflow: hidden; box-shadow: rgba(255, 255, 255, 0.03) 0px 1px 0px inset;}
#pswScreen .feed-row{display: flex; align-items: center; gap: 12px; padding: 12px 14px; border-bottom: 1px solid var(--rb-line); touch-action: manipulation;}
#pswScreen .feed-row:last-child{border-bottom-width: medium; border-bottom-style: none; border-bottom-color: currentcolor;}
#pswScreen .feed-row[onclick]{cursor: pointer; transition: background .14s var(--e);}
#pswScreen .feed-row[onclick]:active{background: var(--rb-elev);}
#pswScreen .feed-body{flex: 1 1 0%; min-width: 0px;}
#pswScreen .feed-client{font-family: var(--rb-sans); font-size: 14px; font-weight: 500; color: var(--rb-text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; letter-spacing: -0.2px;}
#pswScreen .feed-meta{font-family: var(--rb-mono); font-size: 11px; color: var(--rb-dim); margin-top: 2px;}
#pswScreen .feed-right{flex-shrink: 0; text-align: right;}
#pswScreen .feed-hrs{font-family: var(--rb-mono); font-size: 12px; color: var(--psw);}
#pswScreen .feed-tile{width: 40px; height: 40px; border-radius: 12px; flex-shrink: 0; display: flex; align-items: center; justify-content: center; border: 1px solid var(--rb-line2); background: var(--rb-elev); color: var(--rb-dim);}
#pswScreen .feed-tile svg{width: 20px; height: 20px;}
#pswScreen .feed-tile.done{color: var(--green2); border-color: rgba(52, 211, 153, 0.3); background: linear-gradient(160deg, rgba(52, 211, 153, 0.16), rgba(52, 211, 153, 0.04));}
