#pswScreen .active-banner{margin: 12px; background: linear-gradient(165deg,rgba(255,179,64,.06),rgba(255,255,255,.012)),var(--rb-panel); border: 1px solid rgba(255, 179, 64, 0.28); border-radius: 16px; padding: 16px; display: none; box-shadow: rgba(255, 255, 255, 0.05) 0px 1px 0px inset, rgba(0, 0, 0, 0.85) 0px 14px 34px -20px; backdrop-filter: blur(10px);}
